SELECT CAST(rowid AS TEXT) AS legacy_rowid,CAST(CASE WHEN typeof(attempt)='text' THEN attempt END AS TEXT) AS attempt,CAST(CASE WHEN typeof(database)='text' THEN database END AS TEXT) AS database,CAST(CASE WHEN typeof(intent)='text' THEN intent END AS TEXT) AS intent,CAST(CASE WHEN typeof(outcome)='text' THEN outcome END AS TEXT) AS outcome,CAST(CASE WHEN typeof(phase)='text' THEN phase END AS TEXT) AS phase,CAST(CASE WHEN typeof(phase_history)='text' THEN phase_history END AS TEXT) AS phase_history,CAST(CASE WHEN typeof(cleanup_failed)='text' THEN cleanup_failed END AS TEXT) AS cleanup_failed FROM _fleet_sync_transfers
